CASES = [
    {"retrieved": ["p1", "p2"], "relevant": ["p1"], "correct": True},
    {"retrieved": ["p3", "p4"], "relevant": ["p9"], "correct": False},
    {"retrieved": ["p5", "p6"], "relevant": ["p6"], "correct": False},
    {"retrieved": ["p7"],       "relevant": ["p8"], "correct": False},
    {"retrieved": ["p2", "p1"], "relevant": ["p2"], "correct": True},
]

def diagnose(case):
    if case["correct"]:
        return "ok"
    if not set(case["retrieved"]) & set(case["relevant"]):
        return "retrieval"
    return "generation"

def tally(cases):
    counts = {"ok": 0, "retrieval": 0, "generation": 0}
    for c in cases:
        counts[diagnose(c)] += 1
    return counts

from math import comb

def pass_at_k(n, c, k):
    """Chance that at least one of k attempts (drawn from n with c successes) succeeds."""
    return 1 - comb(n - c, k) / comb(n, k)

def pass_hat_k(n, c, k):
    """Chance that all k attempts succeed."""
    return comb(c, k) / comb(n, k)

def check_trajectory(calls, allowed, forbidden, max_steps, needs_before):
    problems = []
    if len(calls) > max_steps:
        problems.append(f"too many steps: {len(calls)} > {max_steps}")
    seen = set()
    for i, call in enumerate(calls):
        tool = call["tool"]
        if tool in forbidden:
            problems.append(f"step {i + 1}: forbidden tool '{tool}'")
        elif tool not in allowed:
            problems.append(f"step {i + 1}: tool '{tool}' is not allowed")
        if tool in needs_before and needs_before[tool] not in seen:
            problems.append(f"step {i + 1}: '{tool}' before '{needs_before[tool]}'")
        seen.add(tool)
    return problems
